export const meta = {
  name: 'build-codemap',
  description: 'Build codemap (analyzer, server, ELK web UI, PyCharm plugin) in parallel, integrate, review, fix',
  phases: [
    { title: 'Build', detail: '4 builders in parallel, one per component' },
    { title: 'Integrate', detail: 'wire together and run end-to-end against gis_api' },
    { title: 'Review', detail: 'analyzer accuracy + UI/UX/e2e review' },
    { title: 'Fix', detail: 'apply confirmed review findings' },
  ],
}

const ROOT = '/home/sushil/PycharmProjects/codemap'
const TARGET = '/home/sushil/PycharmProjects/gis_api'
const COMMON = `You are building one part of "codemap", a local tool at ${ROOT}. READ ${ROOT}/SPEC.md FIRST — it is the contract shared by 4 parallel builders; follow its JSON schema and HTTP API exactly so the parts fit together. Other agents are simultaneously writing the OTHER parts in the same directory: only create/edit files you own (listed below). Never modify anything under ${TARGET} (it is the user's work repo; read-only test target). Python: use /home/sushil/anaconda3/envs/gis_api/bin/python3 (3.13) but code must be stdlib-only and work on 3.10+. Use the scratchpad /tmp/claude-1000/-home-sushil-PycharmProjects-gis-api/679583d0-1cbe-4a24-b9b3-6a164c92c301/scratchpad for temp files. Do not start long-lived background servers you leave running; kill anything you start. Finish with a concise report: files written, how you tested, known limitations.`

const BUILDERS = [
  { key: 'analyzer', prompt: `${COMMON}
YOU OWN: codemap/analyzer.py, codemap/__init__.py, tests/test_analyzer.py (+ tests/fixtures/** if useful).
Implement the analyzer per SPEC "Graph JSON" and "Analyzer rules". Quality matters most here: call resolution through imports, re-exports, self/cls methods with base classes, instantiation, annotated params, FastAPI Depends edges, route prefix resolution (gis_api uses \`router = api_router(prefix="/faq", ...)\` from gis_api/api/envelope.py and gis_api/api/v1/router.py includes routers — inspect them), Celery tasks, __main__ blocks, create_app.
Write unittest tests with small fixture projects. Then run against ${TARGET}: must take < 3 s, report stats, and spot-check 5 HTTP routes by reading their source and confirming the callee edges are right (e.g. faq list_faq -> faq_service.list_public, get_db via depends). Print a summary of entrypoints count by type and resolution rate (resolved vs external calls).` },
  { key: 'server', prompt: `${COMMON}
YOU OWN: codemap/server.py, codemap/__main__.py, tests/test_server.py, README.md.
Implement the server per SPEC "Server HTTP API" (stdlib ThreadingHTTPServer, mtime-poll watcher with debounce, SSE with heartbeats and multiple clients, gzip, /api/source path-safety, /api/open with plugin probe on ports 63342-63352 using GET /api/codemap/ping then /api/codemap/open, fallback to pycharm/charm CLI). Import \`from codemap.analyzer import build_graph, iter_python_files\`; the analyzer is being written in parallel — if it is not there yet when you test, test with a temporary stub injected via monkeypatching in your tests (do NOT write codemap/analyzer.py yourself). CLI: \`python -m codemap <root> [--port 8765] [--host 127.0.0.1] [--exclude GLOB ...] [--no-watch]\`; also handle port-in-use with a clear message. README: what it is, quick start, PyCharm plugin install pointer (pycharm-plugin/), how to run it as an always-on user service: provide scripts/codemap.service (systemd --user unit; WSL may or may not have systemd — check \`ps -p 1 -o comm=\` and document both systemd and a fallback scripts/start-codemap.sh that nohup's it with a pidfile). YOU ALSO OWN scripts/**.
Tests: start the server on an ephemeral port against a temp fixture dir, check /api/graph, SSE event after editing a file, /api/source traversal rejection.` },
  { key: 'frontend', prompt: `${COMMON}
YOU OWN: codemap/web/index.html, codemap/web/app.js, codemap/web/style.css (vendor/elk.bundled.js already exists — global ELK, use \`new ELK()\` with layoutOptions; no workers needed, or use the bundled version's built-in fake worker).
Implement the SPEC "Frontend" section fully. The user explicitly HATES cluttered force-directed/cluster graphs (like GitNexus); they want it to look like a clean ERD / flowchart flowing LEFT -> RIGHT with orthogonal edges, readable cards, easy navigation. Make it polished: Darcula-like dark theme, crisp typography (system UI + JetBrains Mono for code), smooth pan/zoom, animated re-focus is nice-to-have. Key ELK options: algorithm layered, direction RIGHT, edgeRouting ORTHOGONAL, layered.nodePlacement.strategy NETWORK_SIMPLEX or BRANDES_KOEPF, spacing.nodeNodeBetweenLayers ~80, layered.considerModelOrder, portConstraints FIXED_SIDE with WEST in-port and EAST out-port per node.
For testing without the server: write a small fixture JSON in the scratchpad and a tiny static file server, OR if ${ROOT}/codemap/analyzer.py exists by then, generate a real graph via \`python3 -c "import sys,json; sys.path.insert(0,'${ROOT}'); from codemap.analyzer import build_graph; ..."\` against ${TARGET}. Validate JS syntax with \`node --check\`. Test the layout logic headlessly in node: load elk.bundled.js in node (require works) and run your subgraph-building + ELK layout code on the real/fixture graph to ensure it terminates fast (<500ms for 150 nodes) and produces coordinates. Structure app.js so that pure logic (subgraph selection, path finding, search scoring, ELK graph construction) is in functions testable from node (e.g. guard \`if (typeof module !== 'undefined') module.exports = {...}\`). If a headless browser is available (check for chromium / google-chrome / playwright in PATH or npx cache — do not spend long installing), take a screenshot to check visuals.` },
  { key: 'plugin', prompt: `${COMMON}
YOU OWN: pycharm-plugin/** only.
Implement the SPEC "PyCharm plugin" section in Java. Compile with the IDE's bundled JDK: DIST=/home/sushil/.cache/JetBrains/RemoteDev/dist/c4a9ef17c7e8b_pycharm-253.29346.46 ; javac=$DIST/jbr/bin/javac (check jar tool exists in $DIST/jbr/bin; if not, build the jar with python zipfile in build.sh). Classpath: "$DIST/lib/*" plus "$DIST/lib/modules/*" if present (find which jars contain org.jetbrains.ide.HttpRequestHandler, com.intellij.ui.jcef.JBCefBrowser, io.netty classes — use unzip -l / jar tf + grep). The HttpRequestHandler API: override \`isSupported(FullHttpRequest)\` and \`process(QueryStringDecoder urlDecoder, FullHttpRequest request, ChannelHandlerContext context)\`; respond using org.jetbrains.io.Responses helpers or build a DefaultFullHttpResponse manually; check signatures with javap against the actual jars of build 253 — do not guess. Note RestService is an alternative (org.jetbrains.ide.RestService, prefix /api/) — pick whichever compiles cleanly and is simpler; the URL must be /api/codemap/open and /api/codemap/ping. Localhost-only check. Navigation must run on EDT via ApplicationManager.getApplication().invokeLater, use LocalFileSystem.refreshAndFindFileByPath, OpenFileDescriptor.navigate(true), and bring the project frame to front.
Tool window + "Show in Code Map" action per SPEC, plus a simple Settings page (Tools > Code Map) storing the server URL via PropertiesComponent (or a simple applicationConfigurable). Ensure plugin.xml is valid (id dev.codemap.pycharm, since-build 253, vendor, description), icons optional (use AllIcons).
Write pycharm-plugin/build.sh (outputs pycharm-plugin/dist/codemap-pycharm.jar), pycharm-plugin/install.sh (copies to ~/.local/share/JetBrains/PyCharm2025.3/codemap-pycharm/lib/), pycharm-plugin/README.md. RUN build.sh and make it compile with zero errors. DO NOT run install.sh (the user's IDE is live; installation happens later after review). Verify the jar contents (plugin.xml at META-INF/plugin.xml, classes present) and use javap to confirm your classes override the right methods.` },
]

phase('Build')
const built = await parallel(BUILDERS.map(b => () =>
  agent(b.prompt, { label: `build:${b.key}`, phase: 'Build' }).then(r => ({ key: b.key, report: r }))))
const buildReport = built.filter(Boolean).map(b => `### ${b.key}\n${b.report}`).join('\n\n')
log(`Build done: ${built.filter(Boolean).map(b => b.key).join(', ')}`)

phase('Integrate')
const integ = await agent(`${COMMON.replace('only create/edit files you own (listed below)', 'the builders are finished; you may edit any file in ' + ROOT)}
You are the INTEGRATOR. Builder reports:\n${buildReport}\n
Tasks: (1) run all tests (\`cd ${ROOT} && python3 -m unittest discover -s tests -v\`) and fix failures. (2) Start \`python -m codemap ${TARGET} --port 8799\` in the background, verify every API endpoint with curl against SPEC (graph shape incl. fields the frontend reads — grep app.js for every property it accesses and confirm the analyzer emits them with the same names; fix mismatches), SSE delivers an event when a file changes (to test, copy ${TARGET} to the scratchpad and point a second server instance at the COPY, edit a file there — never edit ${TARGET}). (3) Check the frontend loads: all static assets 200, node --check app.js, and run app.js's exported pure logic in node against the REAL /api/graph output for 3 entrypoints (e.g. a GET route, create_app, a celery task) + ELK layout, confirming non-empty focused subgraphs with sensible callees. If a headless browser exists, screenshot. (4) /api/open: plugin is not installed yet so it should return ok:false gracefully with a useful error. (5) Rebuild the plugin with pycharm-plugin/build.sh to confirm it compiles. Kill all servers you started. Report: what you fixed, verification evidence, remaining issues.`, { label: 'integrate', phase: 'Integrate' })

phase('Review')
const FINDINGS = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: {
  severity: { type: 'string', enum: ['high', 'medium', 'low'] }, file: { type: 'string' }, problem: { type: 'string' }, evidence: { type: 'string' }, fix: { type: 'string' } },
  required: ['severity', 'file', 'problem', 'evidence', 'fix'] } } }, required: ['findings'] }
const REVIEWS = [
  { key: 'analyzer-accuracy', prompt: `Review codemap's analyzer accuracy on the real project. Run build_graph on ${TARGET}. Pick 12 diverse functions (routes in different modules, services, repository/adapters, container/build_container, create_app, celery task, a class with inheritance, a method using self.x()). For each, READ the actual source and list the calls it makes, then compare with the graph's outgoing edges + external_calls: report wrong edges (false positives), missed resolvable internal calls (false negatives), wrong entrypoint labels/route prefixes (check prefixes by tracing include_router chains in gis_api/api/v1/router.py and gis_api/main.py manually). Only report concrete, evidenced issues.` },
  { key: 'ui-e2e', prompt: `Review codemap's web UI and server end-to-end as a demanding user who wants a clean ERD-like LEFT->RIGHT flow view (not a cluttered cluster graph), easy navigation, entrypoints, call paths, file paths, Ctrl+click to open in PyCharm, live updates. Start the server on port 8798 against a COPY of ${TARGET} in the scratchpad. Read app.js/index.html/style.css carefully; exercise the logic in node against the real graph; if a headless browser is available, drive it and screenshot (check visually). Look for: JS runtime errors (undefined properties, null derefs when a node has no edges, ids with special chars in URL hash), layout clutter (too many nodes, overlapping labels, edges crossing cards), broken interactions (dblclick refocus, back/forward, expand stubs, path finder, search keyboard nav, Ctrl+click on Mac/Linux metaKey), live reload losing focus, SSE reconnect, performance with large fan-out nodes (e.g. get_db with hundreds of callers). Kill servers afterwards. Only report concrete, evidenced issues.` },
]
const reviews = await parallel(REVIEWS.map(r => () =>
  agent(`${COMMON.replace('only create/edit files you own (listed below)', 'do NOT edit any files — review only')}\n${r.prompt}`, { label: `review:${r.key}`, phase: 'Review', schema: FINDINGS })
    .then(x => ({ key: r.key, findings: (x && x.findings) || [] }))))
const allFindings = reviews.filter(Boolean).flatMap(r => r.findings.map(f => ({ ...f, review: r.key })))
const actionable = allFindings.filter(f => f.severity !== 'low' || allFindings.length < 25)
log(`Review: ${allFindings.length} findings, ${actionable.length} to fix`)

phase('Fix')
let fixReport = 'no findings'
if (actionable.length) {
  fixReport = await agent(`${COMMON.replace('only create/edit files you own (listed below)', 'you may edit any file in ' + ROOT)}
You are the FIXER. Apply these review findings (verify each first; skip any you find incorrect and say why):\n${JSON.stringify(actionable, null, 2)}\n
After fixing: run the test suite, run the analyzer on ${TARGET}, node --check app.js, re-run the node-based layout test on 3 real entrypoints, rebuild the plugin (pycharm-plugin/build.sh). Kill any servers you start. Report per finding: fixed / skipped (reason), plus final verification evidence.`, { label: 'fix', phase: 'Fix' })
}
return { buildReport, integ, findings: allFindings, fixReport }

