package dev.codemap.pycharm;

import com.intellij.openapi.project.DumbAware;
import com.intellij.openapi.project.Project;
import com.intellij.openapi.util.Disposer;
import com.intellij.openapi.wm.ToolWindow;
import com.intellij.ui.content.Content;
import com.intellij.ui.content.ContentFactory;

public final class CodeMapToolWindowFactory implements com.intellij.openapi.wm.ToolWindowFactory, DumbAware {
    public static final String ID = "Code Map";

    @Override
    public void createToolWindowContent(Project project, ToolWindow toolWindow) {
        CodeMapPanel panel = new CodeMapPanel(project);
        Content content = ContentFactory.getInstance().createContent(panel.getComponent(), "", false);
        content.setDisposer(panel);
        toolWindow.getContentManager().addContent(content);
        Disposer.register(toolWindow.getDisposable(), panel);
        project.putUserData(CodeMapPanel.KEY, panel);
    }
}
package dev.codemap.pycharm;

import com.intellij.ide.BrowserUtil;
import com.intellij.openapi.actionSystem.ActionUpdateThread;
import com.intellij.openapi.actionSystem.AnAction;
import com.intellij.openapi.actionSystem.AnActionEvent;
import com.intellij.openapi.actionSystem.CommonDataKeys;
import com.intellij.openapi.editor.Document;
import com.intellij.openapi.editor.Editor;
import com.intellij.openapi.project.DumbAware;
import com.intellij.openapi.project.Project;
import com.intellij.openapi.roots.ProjectFileIndex;
import com.intellij.openapi.vfs.VfsUtilCore;
import com.intellij.openapi.vfs.VirtualFile;
import com.intellij.openapi.wm.ToolWindow;
import com.intellij.openapi.wm.ToolWindowManager;

/** "Show in Code Map": focus the graph on the Python function/class at the caret (or the file's module). */
public final class ShowInCodeMapAction extends AnAction implements DumbAware {

    @Override
    public ActionUpdateThread getActionUpdateThread() {
        return ActionUpdateThread.BGT;
    }

    @Override
    public void update(AnActionEvent e) {
        VirtualFile vf = e.getData(CommonDataKeys.VIRTUAL_FILE);
        boolean ok = e.getProject() != null && vf != null && !vf.isDirectory() && isPython(vf);
        e.getPresentation().setEnabledAndVisible(ok);
    }

    private static boolean isPython(VirtualFile vf) {
        String n = vf.getName();
        return n.endsWith(".py") || n.endsWith(".pyi");
    }

    @Override
    public void actionPerformed(AnActionEvent e) {
        Project project = e.getProject();
        VirtualFile vf = e.getData(CommonDataKeys.VIRTUAL_FILE);
        if (project == null || vf == null) return;
        Editor editor = e.getData(CommonDataKeys.EDITOR);

        String rel = relativePath(project, vf);
        String module = PythonLocator.moduleName(rel != null ? rel : vf.getName());
        String nodeId = null;
        if (module != null) {
            String text = null;
            int line = 0;
            if (editor != null) {
                Document doc = editor.getDocument();
                text = doc.getText();
                line = doc.getLineNumber(editor.getCaretModel().getOffset());
            }
            // No editor (project view): text == null -> focus the module node.
            nodeId = PythonLocator.nodeId(module, text, line);
        }
        showUrl(project, CodeMapSettings.focusUrl(nodeId));
    }

    static String relativePath(Project project, VirtualFile vf) {
        VirtualFile root = null;
        try {
            root = ProjectFileIndex.getInstance(project).getContentRootForFile(vf);
        } catch (Throwable ignored) {}
        if (root != null) {
            String r = VfsUtilCore.getRelativePath(vf, root, '/');
            if (r != null) return r;
        }
        String base = project.getBasePath();
        if (base != null && vf.getPath().startsWith(base + "/")) return vf.getPath().substring(base.length() + 1);
        return null;
    }

    static void showUrl(Project project, String url) {
        if (!CodeMapPanel.isJcefSupported()) {
            BrowserUtil.browse(url);
            return;
        }
        ToolWindow tw = ToolWindowManager.getInstance(project).getToolWindow(CodeMapToolWindowFactory.ID);
        if (tw == null) {
            BrowserUtil.browse(url);
            return;
        }
        tw.activate(() -> {
            CodeMapPanel panel = project.getUserData(CodeMapPanel.KEY);
            if (panel != null && panel.hasBrowser()) panel.open(url);
            else BrowserUtil.browse(url);
        }, true);
    }
}
#!/usr/bin/env bash
# Build dist/codemap-pycharm.jar with the IDE's bundled JBR javac against the local PyCharm jars (no Gradle).
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DIST="${PYCHARM_DIST:-/home/sushil/.cache/JetBrains/RemoteDev/dist/c4a9ef17c7e8b_pycharm-253.29346.46}"
JAVAC="${JAVAC:-$DIST/jbr/bin/javac}"
PYTHON="${PYTHON:-$(command -v python3 || command -v python)}"

[ -x "$JAVAC" ] || { echo "javac not found: $JAVAC (set PYCHARM_DIST or JAVAC)" >&2; exit 1; }
[ -d "$DIST/lib" ] || { echo "IDE lib dir not found: $DIST/lib" >&2; exit 1; }

CP="$DIST/lib/*"
[ -d "$DIST/lib/modules" ] && CP="$CP:$DIST/lib/modules/*"

BUILD="$HERE/build"
OUT="$HERE/dist"
rm -rf "$BUILD"
mkdir -p "$BUILD/classes" "$OUT"

find "$HERE/src/main/java" -name '*.java' > "$BUILD/sources.txt"
echo "Compiling $(wc -l < "$BUILD/sources.txt") sources with $JAVAC"
"$JAVAC" --release 21 -encoding UTF-8 -nowarn -Xlint:-options \
  -cp "$CP" -d "$BUILD/classes" @"$BUILD/sources.txt"

cp -r "$HERE/src/main/resources/." "$BUILD/classes/"

JAR="$OUT/codemap-pycharm.jar"
rm -f "$JAR"
if [ -x "$DIST/jbr/bin/jar" ]; then
  (cd "$BUILD/classes" && "$DIST/jbr/bin/jar" cf "$JAR" .)
else
  # JBR ships without the `jar` tool: package with Python's zipfile (a jar is a zip).
  "$PYTHON" - "$BUILD/classes" "$JAR" <<'PY'
import os, sys, zipfile
src, jar = sys.argv[1], sys.argv[2]
with zipfile.ZipFile(jar, "w", zipfile.ZIP_DEFLATED) as z:
    z.writestr("META-INF/MANIFEST.MF", "Manifest-Version: 1.0\r\nCreated-By: codemap build.sh\r\n\r\n")
    for dp, dn, fn in os.walk(src):
        dn.sort()
        for f in sorted(fn):
            full = os.path.join(dp, f)
            arc = os.path.relpath(full, src).replace(os.sep, "/")
            if arc == "META-INF/MANIFEST.MF":
                continue
            z.write(full, arc)
PY
fi
echo "Built $JAR"
