package dev.codemap.pycharm;

import com.intellij.ide.BrowserUtil;
import com.intellij.openapi.fileEditor.FileEditor;
import com.intellij.openapi.fileEditor.FileEditorManager;
import com.intellij.openapi.project.Project;
import com.intellij.openapi.util.Key;

/** Opens (or re-uses) the "Code Map" editor tab of a project. */
public final class CodeMapTabs {
    private static final Key<CodeMapVirtualFile> FILE_KEY = Key.create("dev.codemap.pycharm.file");

    private CodeMapTabs() {}

    /** Open the Code Map tab; navigate it to {@code url} (null = keep current page / server home). */
    public static void open(Project project, String url) {
        if (!CodeMapPanel.isJcefSupported()) {
            BrowserUtil.browse(url != null ? url : CodeMapSettings.getServerUrl());
            return;
        }
        FileEditorManager fem = FileEditorManager.getInstance(project);
        CodeMapVirtualFile file = project.getUserData(FILE_KEY);
        boolean alreadyOpen = file != null && fem.isFileOpen(file);
        if (file == null) {
            file = new CodeMapVirtualFile(url);
            project.putUserData(FILE_KEY, file);
        } else if (!alreadyOpen) {
            file.initialUrl = url;  // editor will be re-created with this URL
        }
        FileEditor[] editors = fem.openFile(file, true);
        if (alreadyOpen && url != null) {
            for (FileEditor ed : editors) {
                if (ed instanceof CodeMapFileEditor) {
                    ((CodeMapFileEditor) ed).getPanel().open(url);
                    break;
                }
            }
        }
    }
}
