def serve(root: str | None, host: str = "127.0.0.1", port: int = 8765,
          excludes: list[str] | None = None, watch: bool = True) -> None:
    registry = ProjectRegistry(lambda r: CodemapApp(r, excludes, watch=watch))
    httpd = make_server(registry, host, port)  # bind first so port errors surface before the build
    shown = "127.0.0.1" if host in ("0.0.0.0", "") else host
    base = f"http://{shown}:{httpd.server_address[1]}"
