        registry.default_id = app.id
        print(f"codemap: serving {app.root} at {base}/  (also {base}/p/{app.id}/)", flush=True)
    print(f"codemap: per-project maps at {base}/open?root=<abs project path>  (list: {base}/projects)"
          f"  (watch={'on' if watch else 'off'})", flush=True)
    registry.start()
    try:
