@CacheableTask
abstract class StageCodemapServer : DefaultTask() {
    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    @get:IgnoreEmptyDirectories
    abstract val sourceDir: DirectoryProperty

    @get:Input
    abstract val pluginVersion: Property<String>

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    private val skipDirs = setOf("__pycache__", "tests", "test", ".pytest_cache", ".mypy_cache")

    private fun collect(root: File, dir: File, rel: String, out: MutableList<String>) {
        val inWeb = rel == "web" || rel.startsWith("web/")
        dir.listFiles().orEmpty().sortedBy { it.name }.forEach { f ->
            val r = if (rel.isEmpty()) f.name else "$rel/${f.name}"
            if (f.isDirectory) {
                if (f.name !in skipDirs && !f.name.startsWith(".") && !Files.isSymbolicLink(f.toPath())) {
                    collect(root, f, r, out)
                }
            } else if (f.isFile) {
                val n = f.name
                if (n.endsWith(".pyc") || n.endsWith(".pyo") || n.startsWith(".")) return@forEach
                if (!inWeb && !n.endsWith(".py")) return@forEach
                out += r
            }
        }
    }

    @TaskAction
    fun stage() {
        val src = sourceDir.get().asFile
        require(src.resolve("__main__.py").isFile) { "codemap package not found: $src (set -PcodemapServerSource)" }
        val files = mutableListOf<String>().also { collect(src, src, "", it) }.sorted()
        val dest = outputDir.get().asFile.resolve("codemap-server")
        dest.deleteRecursively()
        val sha1 = MessageDigest.getInstance("SHA-1")
        for (rel in files) {
            val data = src.resolve(rel).readBytes()
            sha1.update(rel.toByteArray(Charsets.UTF_8)); sha1.update(0)
            sha1.update(data); sha1.update(0)
            dest.resolve("codemap/$rel").apply { parentFile.mkdirs() }.writeBytes(data)
        }
        dest.resolve("FILES").writeText(files.joinToString("") { "codemap/$it\n" })
        val full = pluginVersion.get() + "-" + sha1.digest().joinToString("") { "%02x".format(it) }.take(10)
        dest.resolve("VERSION").writeText(full + "\n")
        logger.lifecycle("Bundled ${files.size} server files, VERSION $full")
    }
}

