package com.sushil.codemap.analysis;

import com.jetbrains.python.psi.PyFile;

/** STUB - replaced by the analyzer port. Returns only the module node. */
final class PsiFileAnalyzer implements FileAnalyzer {
    @Override
    public FileResult analyze(PyFile file, String relPath) {
        FileResult r = new FileResult();
        r.relPath = relPath;
        String mod = relPath.replaceAll("\\.pyi?$", "").replace('/', '.').replaceAll("\\.__init__$", "");
        r.module = mod;
        java.util.Map<String, Object> n = new java.util.LinkedHashMap<>();
        n.put("id", mod + ":" + mod);
        n.put("kind", "module");
        n.put("name", mod);
        n.put("qualname", mod);
        n.put("module", mod);
        n.put("file", relPath);
        n.put("line", 1);
        r.nodes.add(n);
        return r;
    }
}
